"""Step 5b (PD-24): the OpenAPI component schemas, generated by ``gen-json-schema`` and trimmed, on the toy library."""

import json
from pathlib import Path

import pytest

from rdf_persistence.core.services.artifacts import COMPONENTS_FILE
from rdf_persistence.schema.services.schema import SERVED_SCHEMAS, load_schema
from rdf_persistence.schema.services.schema_structure import is_bookkeeping, is_internal
from rdf_persistence_generation.components import TYPE_SCHEMA, render
from rdf_persistence_generation.steps import COMPONENTS_STEP

from .conftest import ROOT_SCHEMA, TOY
from .golden import TOY_TARGET, assert_matches_toy, run_toy

BOOKKEEPING = {"created", "modified", "creator", "contributor", "version"}


@pytest.fixture(scope="module")
def rendered(tmp_path_factory: pytest.TempPathFactory) -> Path:
    return run_toy(COMPONENTS_STEP, tmp_path_factory.mktemp("components"))


@pytest.fixture(scope="module")
def schemas(rendered: Path) -> dict:
    text = (rendered / str(TOY_TARGET.python) / COMPONENTS_FILE).read_text(encoding="utf-8")
    return json.loads(text)["schemas"]


def test_the_output_equals_the_committed_tree(rendered: Path) -> None:
    assert_matches_toy(rendered, f"generated/{COMPONENTS_FILE}")


def test_every_class_of_the_schema_has_a_component_schema(schemas: dict) -> None:
    view = load_schema(TOY / ROOT_SCHEMA)
    assert {"Book", "Chapter", "Note", "Scan", "Library", "Genre"} <= set(schemas), (
        "every class has a component schema"
    )
    assert set(view.all_classes()) <= set(schemas), "a schema for every class"


def test_the_references_point_into_the_components_of_an_openapi_document(schemas: dict) -> None:
    text = json.dumps(schemas)
    assert "#/$defs/" not in text, "no reference points into the JSON-schema definitions"
    assert schemas["Book"]["properties"]["chapters"]["items"] == {
        "$ref": "#/components/schemas/Chapter"
    }, "the references point into the components"


def test_no_bookkeeping_slot_is_in_any_schema(schemas: dict) -> None:
    leaked = {
        (name, prop)
        for name, schema in schemas.items()
        for prop in schema.get("properties", {})
        if prop in BOOKKEEPING
    }
    assert not leaked, "the session writes them; the API never shows them"


def test_the_bookkeeping_and_internal_slots_of_every_class_are_left_out(schemas: dict) -> None:
    view = load_schema(TOY / ROOT_SCHEMA)
    for cls in view.all_classes():
        hidden = {
            s.name for s in view.class_induced_slots(cls) if is_bookkeeping(s) or is_internal(s)
        }
        assert not hidden & set(schemas[cls].get("properties", {})), cls


def test_a_required_slot_that_is_left_out_is_no_longer_required(schemas: dict) -> None:
    assert not BOOKKEEPING & set(schemas["Book"].get("required", [])), (
        "no bookkeeping slot is required"
    )
    assert schemas["Book"]["required"] == ["id", "label"], (
        "the required slots are the identifier and the label"
    )


def test_the_identifier_is_read_only_because_the_service_assigns_it(schemas: dict) -> None:
    assert schemas["Book"]["properties"]["id"]["readOnly"] is True, "the identifier is read-only"
    assert "readOnly" not in schemas["Book"]["properties"]["label"], "the label is not read-only"


def test_the_output_is_reproducible(rendered: Path, tmp_path: Path) -> None:
    again = run_toy(COMPONENTS_STEP, tmp_path)
    name = Path(str(TOY_TARGET.python)) / COMPONENTS_FILE
    assert (again / name).read_bytes() == (rendered / name).read_bytes(), (
        "the output is the same each time"
    )


def test_a_target_that_serves_nothing_gets_no_components_file(tmp_path: Path) -> None:
    quiet = TOY_TARGET.model_copy(update={"openapi": False})
    staged = run_toy(COMPONENTS_STEP, tmp_path, quiet)
    assert not list(staged.rglob(COMPONENTS_FILE)), "the target switched the step off"


def test_every_class_schema_lists_an_optional_type_property(schemas: dict) -> None:  # #148
    for name, schema in schemas.items():
        if "properties" in schema:
            assert schema["properties"]["type"] == TYPE_SCHEMA, name
            assert "type" not in schema.get("required", []), f"{name}: the type is optional"


def _names(schema_path: Path) -> list[str]:
    [file] = render(schema_path)
    return list(json.loads(file.text)["schemas"])


def test_a_served_schema_leaves_the_classes_of_another_served_schema_to_its_file() -> None:  # TC-21
    """A schema that imports a served one would publish its classes twice: the merge refuses that."""
    iris, persistence, migrations, access, tenancy, events, collaboration, service = (
        _names(path) for path in SERVED_SCHEMAS
    )
    assert {"IriPolicy", "ServiceSettings", "IdSpec", "IdKind"} <= set(iris), "its own classes"
    assert not {"IriPolicy", "ServiceSettings", "IdSpec", "IdKind"} & set(service), (
        "the importing schema leaves them to the file of the schema that declares them"
    )
    assert {"Page", "Filter", "ListPlan", "AggregateHead"} <= set(persistence), "its own classes"
    assert {"Migration", "MigrationStep"} <= set(migrations), "its own classes"
    assert {"VerifiedCaller", "GrantSet", "CallerAccess", "AccountSummary"} <= set(access), (
        "its own classes"
    )
    assert {"TenantDump", "TenantSummary"} <= set(tenancy), "its own classes"
    assert {"EventEnvelope"} <= set(events), "its own class"
    assert {"Referrer", "ReferrerList", "MemberList"} <= set(collaboration), "its own classes"
    assert {"Problem", "TenantCreate"} <= set(service), "its own classes stay"
    served = {
        "iris": iris,
        "persistence": persistence,
        "migrations": migrations,
        "access": access,
        "tenancy": tenancy,
        "events": events,
        "collaboration": collaboration,
        "service": service,
    }
    twice = {
        name
        for name in {n for names in served.values() for n in names}
        if sum(name in names for names in served.values()) > 1
    }
    assert not twice, f"names in two of the served files: {sorted(twice)}"


def test_a_metamodel_class_that_two_served_schemas_import_is_in_the_first_one_only() -> None:
    """The migrations and the service schemas both reach the metamodel; the earlier one publishes it."""
    migrations, service = (_names(path) for path in (SERVED_SCHEMAS[2], SERVED_SCHEMAS[-1]))
    shared = set(migrations) & {"AggregateKey", "Described"}
    assert shared, "the earlier schema publishes the metamodel classes it imports"
    assert not shared & set(service), "the later one leaves them to it"


OWN_TYPE_SCHEMA = """
id: https://example.org/ns/typed
name: typed
title: Typed
description: A class with a slot named type.
prefixes: {v: "https://example.org/ns/v#", linkml: "https://w3id.org/linkml/"}
default_prefix: v
default_range: string
imports: [linkml:types]
classes:
  Typed:
    title: Typed
    description: Has its own type slot.
    slots: [id, type]
slots:
  id: {title: Id, description: The id., identifier: true, range: string}
  type: {title: Type, description: Its own kind., range: integer}
"""


def test_a_class_with_its_own_type_slot_keeps_its_definition(tmp_path: Path) -> None:
    (tmp_path / "typed.yaml").write_text(OWN_TYPE_SCHEMA, encoding="utf-8")
    [file] = render(tmp_path / "typed.yaml")
    prop = json.loads(file.text)["schemas"]["Typed"]["properties"]["type"]
    assert prop["type"] == "integer", "its own definition stays, not the generic string"
    assert "Its own kind." in prop.get("description", ""), "its own description stays"
